use super::*;
use crate::{DslValue,source_fixture::receive};
#[path="📥️driver/🦀️.rs"]mod driver;
use driver::*;
#[test]
fn native_shared_original_receive_exact_prefix_cancellation_and_transfer(){let vectors=fixture();for law in vectors["cases"].as_array().unwrap(){let mut complete=0;for cut in 0..1000{let mut bank=bank();let original=source(DslValue::String(law["original"].as_str().unwrap().to_owned()),&mut bank);let foreign=source(DslValue::String(law["original"].as_str().unwrap().to_owned()),&mut bank);let(mut receiver,h)=crate::observe_retirement_allocations(<SealedShared<String>as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut turns=0;while !receiver.output_ready()&&turns<cut{let d=receiver.demands(original.borrow(),4096).unwrap();deny(&mut receiver,original.borrow(),&mut control,&mut bank,d);let g=bank.loan(1,4096);original_turn(&mut receiver,original.borrow(),&mut control,g,&mut bank).unwrap();turns+=1;if receiver.binding.is_some()&&!receiver.output_ready(){assert!(receiver.demands(foreign.borrow(),4096).is_err());}}if receiver.output_ready(){complete=turns;assert!(!receiver.child.reserved());assert!(receiver.retired_header.is_none());assert!(receiver.raw.is_none());let pointer=receiver.output.as_ref().unwrap().get().as_ptr();let value=take(&mut receiver,&mut bank);assert_eq!(value.get().as_ptr(),pointer);assert_eq!(value.get(),law["expected"].as_str().unwrap());drain(value,&mut bank);}close(&mut receiver,&mut bank);drain(original,&mut bank);drain(foreign,&mut bank);if complete>0&&cut>complete{break}}assert!(complete>0)}}
#[test]
fn native_shared_original_callback_refusal_retains_paid_child_authority(){let mut bank=bank();let original=source(DslValue::String("authored original".to_owned()),&mut bank);let mut receiver=<SealedShared<String>as NativeReceive<DslValue>>::receiver();let admitted=std::cell::Cell::new(true);let mut callback=|_|admitted.get();let mut control=NativeDecodeControl::new(1<<20,&mut callback);for _ in 0..100{if receiver.phase==Phase::Receive{break}let g=bank.loan(1,4096);original_turn(&mut receiver,original.borrow(),&mut control,g,&mut bank).unwrap();}assert!(receiver.child.initialized());let pointer=receiver.child.address();admitted.set(false);let g=bank.loan(1,4096);let(t,h)=crate::observe_retirement_allocations(||receive(&mut control,g,bank.work_loan(1),|c|receiver.advance(original.borrow(),c,4096,g)));assert!(t.result.is_err());assert_eq!(h,(0,0));let p=t.result.as_ref().unwrap_err().retained_progress();bank.post(p,t.work,g,h);assert_eq!(receiver.child.address(),pointer);assert!(!receiver.output_ready());close(&mut receiver,&mut bank);drain(original,&mut bank);}
